test("param name followed by astral ID_Continue should be quoted", () => {
  // 𝕏 (U+1D54F) is an astral ID_Continue character
  // When parsing "/:foo 𝕏bar", the parser splits into code points correctly,
  // but stringify must also handle this correctly by quoting the param name
  const path = "/:foo 𝕏bar";
  const tokens = parse(path);
  expect(tokens).toBeDefined();
  // The param name should be quoted to prevent "foo" from merging with "𝕏bar" on round-trip
  const str = stringify(tokens);
  expect(str).toBe('/:"foo" 𝕏bar');
  // Verify round-trip
  const tokens2 = parse(str);
  expect(tokens2).toBeDefined();
  expect(stringify(tokens2)).toBe(str);
});

