test("param name followed by astral ID_Continue should be quoted", () => {
  // 𝕏 (U+1D54F) is an astral ID_Continue character
  // When a param is followed by text starting with an astral ID_Continue character,
  // the name must be quoted to prevent the astral char from merging into the param name on re-parse.
  const tokens = parse("/:foo 𝕏bar");
  expect(tokens).toBeDefined();
  // Without the fix, stringify would produce "/:foo 𝕏bar" which re-parses incorrectly
  const str = stringify(tokens);
  // The name should be quoted to prevent "foo" from merging with "𝕏bar" on round-trip
  expect(str).toBe('/:"foo" 𝕏bar');
  // Verify round-trip
  const tokens2 = parse(str);
  expect(tokens2).toBeDefined();
  expect(stringify(tokens2)).toBe(str);
});

