import { describe, test, expect } from "vitest";
import { parse, stringify, TokenData, Parameter, Wildcard, Text, Group, Token } from "../src/index.js";

describe("path-to-regexp regression", () => {
  test("basic parse/stringify", () => {
    const tokens = parse("/user/:id");
    expect(tokens).toBeDefined();
    const str = stringify(tokens);
    expect(str).toBe("/user/:id");
  });
  test("wildcard", () => {
    const tokens = parse("/*splat");
    expect(tokens).toBeDefined();
  });
  test("param name followed by astral ID_Continue should be quoted", () => {
    // When a param is directly followed by a character that is ID_Continue,
    // the parser includes it in the param name.
    // But if we have a param followed by text where the first char is astral ID_Continue,
    // stringify should quote to maintain round-trip.
    // Example: ':foo bar' has param 'foo' followed by text ' bar'
    // ':foo_tigers' has param 'foo_tigers' (underscore is ID_Continue)
    // ':foo Tigers' has param 'foo' followed by text ' Tigers'
    const tokens = parse("/:foo Tigers");
    expect(tokens).toBeDefined();
    const str = stringify(tokens);
    // 'T' is ID_Continue so the name needs quoting to prevent 'fooTigers' being parsed
    expect(str).toBe('/:"foo" Tigers');
    // Verify round-trip
    const tokens2 = parse(str);
    expect(tokens2).toBeDefined();
    expect(stringify(tokens2)).toBe(str);
  });
  test("param followed by astral ID_Continue in text token", () => {
    // Construct tokens manually to test the case where:
    // 1. We have a param 'foo'
    // 2. Followed by text starting with astral ID_Continue '𝕏bar'
    // stringifyName must quote 'foo' because 𝕏 is ID_Continue
    const data = new TokenData([
      { type: "text", value: "/" },
      { type: "param", name: "foo" },
      { type: "text", value: "𝕏bar" },
    ]);
    const str = stringify(data);
    // Must quote 'foo' because next text starts with astral ID_Continue 𝕏
    expect(str).toBe('/:"foo"𝕏bar');
    // Round-trip: unquoted ':foo𝕏bar' would parse as param name 'foo𝕏bar'
  });
});

